  ('00000000-0000-4000-8000-000000000001', 'openalex-W3110709293', '{"paperId":"openalex-W3110709293","projectId":"00000000-0000-4000-8000-000000000001","overview":"Three-wave study of 2,109 secondary school teens: addiction-like social media problems, not intensity of use, predicted later lower mental health, partly via social comparison and cybervictimisation.","whyItMatters":"Distinguishes problematic use from simply using a lot — central to your claims.","relevance":96,"relevanceReason":"Directly tests use vs problems","stances":[{"claimId":"c1","stance":"challenges","note":"Intensity alone did not predict poorer mental health"},{"claimId":"c2","stance":"supports","note":"Problematic use, not time, drives effects"},{"claimId":"c3","stance":"unclear","note":"not stated"}],"methodology":"Three-wave longitudinal; random-intercept cross-lagged panel models.","limitations":"Self-report measures; secondary school sample only.","useAs":"evidence"}'::jsonb, '{"score":94,"inputs":{"citationCount":330,"peerReviewed":true,"venueType":"journal","year":2020}}'::jsonb),
  ('00000000-0000-4000-8000-000000000001', 'openalex-W3195706482', '{"paperId":"openalex-W3195706482","projectId":"00000000-0000-4000-8000-000000000001","overview":"Umbrella review of 25 reviews (2019–2021). Most describe links between social media use and adolescent mental health as weak or inconsistent; a few call them substantial and harmful.","whyItMatters":"Strongest high-level evidence that the overall effect is small and contested.","relevance":94,"relevanceReason":"Synthesises the whole debate","stances":[{"claimId":"c1","stance":"challenges","note":"Most reviews find weak or inconsistent associations"},{"claimId":"c2","stance":"neutral","note":"Explains divergent interpretations"},{"claimId":"c3","stance":"unclear","note":"not stated"}],"methodology":"Umbrella review of 7 meta-analyses, 9 systematic and 9 narrative reviews.","limitations":"Only covers reviews to mid-2021; inherits their biases.","useAs":"counterpoint"}'::jsonb, '{"score":100,"inputs":{"citationCount":746,"peerReviewed":true,"venueType":"journal","year":2021}}'::jsonb),
  ('00000000-0000-4000-8000-000000000001', 'openalex-W2908500884', '{"paperId":"openalex-W2908500884","projectId":"00000000-0000-4000-8000-000000000001","overview":"In 10,904 UK 14-year-olds, heavier social media use was linked to more depressive symptoms, more strongly for girls, partly via harassment, poor sleep, self-esteem and body image.","whyItMatters":"Large cohort evidence of a dose–response link, with plausible pathways.","relevance":92,"relevanceReason":"Key quantitative evidence for harm","stances":[{"claimId":"c1","stance":"supports","note":"Higher daily use linked to more depressive symptoms"},{"claimId":"c2","stance":"supports","note":"Effects run through harassment, sleep and body image"},{"claimId":"c3","stance":"unclear","note":"not stated"}],"methodology":"Cross-sectional regression and path models, Millennium Cohort Study.","limitations":"Cross-sectional; cannot establish causal direction.","useAs":"evidence"}'::jsonb, '{"score":95,"inputs":{"citationCount":733,"peerReviewed":true,"venueType":"journal","year":2018}}'::jsonb),
  ('00000000-0000-4000-8000-000000000001', 'openalex-W4322582728', '{"paperId":"openalex-W4322582728","projectId":"00000000-0000-4000-8000-000000000001","overview":"Following 3,228 UK young people, more social media use at 12–13 predicted worse mental health at 14–15, partly through lower self-esteem.","whyItMatters":"Longitudinal UK evidence that use precedes poorer mental health.","relevance":91,"relevanceReason":"Temporal evidence on causation","stances":[{"claimId":"c1","stance":"supports","note":"Earlier use predicts later difficulties"},{"claimId":"c2","stance":"neutral","note":"Mediated by self-esteem, not use type"},{"claimId":"c3","stance":"unclear","note":"not stated"}],"methodology":"Longitudinal observational study, Understanding Society, mediation analysis.","limitations":"Observational; hours measured on a coarse scale.","useAs":"evidence"}'::jsonb, '{"score":88,"inputs":{"citationCount":56,"peerReviewed":true,"venueType":"journal","year":2023}}'::jsonb),
  ('00000000-0000-4000-8000-000000000001', 'openalex-W4393176161', '{"paperId":"openalex-W4393176161","projectId":"00000000-0000-4000-8000-000000000001","overview":"Umbrella review of 24 quality-assessed reviews (2015–2023) on risks and opportunities of social media for 10–19-year-olds, plus proposed ways to reduce risk.","whyItMatters":"Covers both harms and benefits, plus mitigation — balanced evidence for your essay.","relevance":90,"relevanceReason":"Recent, quality-appraised synthesis","stances":[{"claimId":"c1","stance":"neutral","note":"Relationship shaped by many intervening factors"},{"claimId":"c2","stance":"supports","note":"Effects depend on intervening factors"},{"claimId":"c3","stance":"neutral","note":"Summarises mitigation proposals"}],"methodology":"Umbrella review following PRIOR; AMSTAR 2 quality assessment.","limitations":"Depends on quality of included reviews.","useAs":"background"}'::jsonb, '{"score":97,"inputs":{"citationCount":115,"peerReviewed":true,"venueType":"journal","year":2024}}'::jsonb),
  ('00000000-0000-4000-8000-000000000001', 'openalex-W4412412329', '{"paperId":"openalex-W4412412329","projectId":"00000000-0000-4000-8000-000000000001","overview":"Narrative review of interventions for problematic social media use in 10–20-year-olds: teaching healthy-use strategies works better long-term than restricting use or warning of harms.","whyItMatters":"Direct evidence on which interventions actually help teens.","relevance":89,"relevanceReason":"Only source on interventions","stances":[{"claimId":"c1","stance":"neutral","note":"Focus is interventions, not causation"},{"claimId":"c2","stance":"supports","note":"Targets problematic use rather than time"},{"claimId":"c3","stance":"supports","note":"Skills-based programs beat restriction"}],"methodology":"Narrative review of recent intervention studies.","limitations":"Narrative, not systematic; heterogeneous interventions.","useAs":"evidence"}'::jsonb, '{"score":86,"inputs":{"citationCount":24,"peerReviewed":true,"venueType":"journal","year":2025}}'::jsonb),
  ('00000000-0000-4000-8000-000000000001', 'openalex-W4396694082', '{"paperId":"openalex-W4396694082","projectId":"00000000-0000-4000-8000-000000000001","overview":"A review arguing that research should focus on how social media amplifies normal adolescent developmental changes in behaviour, cognition and neurobiology that already raise vulnerability to socio-emotional disorders.","whyItMatters":"Offers mechanisms, not just correlations, to explain when social media harms adolescents.","relevance":88,"relevanceReason":"Directly theorises causal pathways","stances":[{"claimId":"c1","stance":"neutral","note":"Argues mixed evidence needs mechanistic framing"},{"claimId":"c2","stance":"supports","note":"Harm depends on specific behaviours and cognitions"},{"claimId":"c3","stance":"unclear","note":"Interventions not discussed in abstract"}],"methodology":"Narrative review of developmental and social media research.","limitations":"No new data; mechanisms proposed rather than tested.","useAs":"background"}'::jsonb, '{"score":100,"inputs":{"citationCount":214,"peerReviewed":true,"venueType":"journal","year":2024}}'::jsonb),
  ('00000000-0000-4000-8000-000000000001', 'openalex-W4410090858', '{"paperId":"openalex-W4410090858","projectId":"00000000-0000-4000-8000-000000000001","overview":"Registered Report with 3,340 UK 11–19-year-olds: those with diagnosed mental health conditions spend more time on social media and compare themselves more, varying by condition type.","whyItMatters":"Shows the link differs for clinically affected teens — nuance your argument needs.","relevance":86,"relevanceReason":"Clinical sample adds rare nuance","stances":[{"claimId":"c1","stance":"neutral","note":"Shows differences, not causation"},{"claimId":"c2","stance":"supports","note":"Use patterns differ by condition type"},{"claimId":"c3","stance":"unclear","note":"not stated"}],"methodology":"Registered Report; nationally representative survey with clinical diagnostic ratings.","limitations":"Cross-sectional; self-reported social media measures.","useAs":"evidence"}'::jsonb, '{"score":97,"inputs":{"citationCount":72,"peerReviewed":true,"venueType":"journal","year":2025}}'::jsonb),
  ('00000000-0000-4000-8000-000000000001', 'openalex-W4226441341', '{"paperId":"openalex-W4226441341","projectId":"00000000-0000-4000-8000-000000000001","overview":"Proposes a cognitive behavioural model where social media is helpful or harmful depending on whether it meets teens'' needs for acceptance and belonging.","whyItMatters":"Gives a clinical theory for why the same use helps some teens and harms others.","relevance":80,"relevanceReason":"Theory for nuanced claim","stances":[{"claimId":"c1","stance":"challenges","note":"Use can be helpful as well as harmful"},{"claimId":"c2","stance":"supports","note":"Function of use matters more than amount"},{"claimId":"c3","stance":"neutral","note":"Implies clinical, not restrictive, approaches"}],"methodology":"Theoretical model from clinical experience and literature.","limitations":"Not empirically tested.","useAs":"background"}'::jsonb, '{"score":80,"inputs":{"citationCount":31,"peerReviewed":true,"venueType":"journal","year":2022}}'::jsonb),
  ('00000000-0000-4000-8000-000000000001', 'openalex-W4409765642', '{"paperId":"openalex-W4409765642","projectId":"00000000-0000-4000-8000-000000000001","overview":"Scoping review of recent reviews finding inconsistent results: social media shows both negative and positive effects on youth mental health, with clear knowledge gaps.","whyItMatters":"Recent confirmation that evidence remains mixed — good for framing.","relevance":78,"relevanceReason":"Recent but overlaps other reviews","stances":[{"claimId":"c1","stance":"challenges","note":"Finds both negative and positive effects"},{"claimId":"c2","stance":"neutral","note":"not stated in abstract"},{"claimId":"c3","stance":"unclear","note":"not stated"}],"methodology":"Scoping review of reviews, Arksey and O''Malley framework.","limitations":"Review of reviews; limited depth on individual studies.","useAs":"counterpoint"}'::jsonb, '{"score":97,"inputs":{"citationCount":74,"peerReviewed":true,"venueType":"journal","year":2025}}'::jsonb),
  ('00000000-0000-4000-8000-000000000001', 'openalex-W4387900607', '{"paperId":"openalex-W4387900607","projectId":"00000000-0000-4000-8000-000000000001","overview":"Survey of 2,023 adolescents (mean age 17) suggesting common problematic-use scales inflate prevalence; specific activities and motivations better explain mental health outcomes.","whyItMatters":"Questions how ''problematic use'' is measured — a useful critique.","relevance":76,"relevanceReason":"Methodological critique","stances":[{"claimId":"c1","stance":"challenges","note":"Existing scales overstate problematic use"},{"claimId":"c2","stance":"supports","note":"Specific activities matter, not overall use"},{"claimId":"c3","stance":"unclear","note":"not stated"}],"methodology":"Cross-sectional survey; exploratory graph and factor analyses.","limitations":"Cross-sectional; conference abstract.","useAs":"method"}'::jsonb, '{"score":60,"inputs":{"citationCount":0,"peerReviewed":true,"venueType":"journal","year":2023}}'::jsonb),
  ('00000000-0000-4000-8000-000000000001', 'openalex-W3049699106', '{"paperId":"openalex-W3049699106","projectId":"00000000-0000-4000-8000-000000000001","overview":"Scoping review mapping five years of research on social media and adolescent wellbeing, finding a fast-growing, polarised and hard-to-follow body of evidence.","whyItMatters":"Useful map of the field for your introduction and background section.","relevance":74,"relevanceReason":"Broad overview, less specific","stances":[{"claimId":"c1","stance":"neutral","note":"Describes polarised findings"},{"claimId":"c2","stance":"unclear","note":"not stated in abstract"},{"claimId":"c3","stance":"unclear","note":"not stated"}],"methodology":"Scoping review of literature from the previous five years.","limitations":"Descriptive mapping; no quality appraisal stated.","useAs":"background"}'::jsonb, '{"score":93,"inputs":{"citationCount":284,"peerReviewed":true,"venueType":"journal","year":2020}}'::jsonb),
  ('00000000-0000-4000-8000-000000000001', 'openalex-W7110479187', '{"paperId":"openalex-W7110479187","projectId":"00000000-0000-4000-8000-000000000001","overview":"Literature review asking whether active (posting, engaging) or passive (scrolling) social media use has a bigger effect on adolescent mental health.","whyItMatters":"Directly addresses the active-versus-passive distinction in your second claim.","relevance":73,"relevanceReason":"Targets claim 2 directly","stances":[{"claimId":"c1","stance":"neutral","note":"not stated in abstract"},{"claimId":"c2","stance":"supports","note":"Frames type of use as key"},{"claimId":"c3","stance":"unclear","note":"not stated"}],"methodology":"PRISMA-guided literature review of MEDLINE and PubMed.","limitations":"Student review; findings not stated in abstract.","useAs":"background"}'::jsonb, '{"score":60,"inputs":{"citationCount":0,"peerReviewed":true,"venueType":"journal","year":2024}}'::jsonb),
  ('00000000-0000-4000-8000-000000000001', 'openalex-W4412188505', '{"paperId":"openalex-W4412188505","projectId":"00000000-0000-4000-8000-000000000001","overview":"Meta-analytic synthesis of 30+ studies finding fear of missing out mediates links between social media frequency, passive browsing and adolescent depression and anxiety.","whyItMatters":"Points to FoMO and passive use as the mechanism — supports nuance.","relevance":72,"relevanceReason":"Mechanism-focused, lower-tier venue","stances":[{"claimId":"c1","stance":"neutral","note":"Effects run through FoMO"},{"claimId":"c2","stance":"supports","note":"Passive browsing worse than active socialising"},{"claimId":"c3","stance":"unclear","note":"not stated"}],"methodology":"Bibliometric and meta-analysis of 30+ empirical studies.","limitations":"Methods detail not stated in abstract; venue not peer-review verified.","useAs":"evidence"}'::jsonb, '{"score":64,"inputs":{"citationCount":1,"peerReviewed":true,"venueType":"journal","year":2025}}'::jsonb),
  ('00000000-0000-4000-8000-000000000001', 'openalex-W2751422871', '{"paperId":"openalex-W2751422871","projectId":"00000000-0000-4000-8000-000000000001","overview":"Survey of 113 US parent–teen pairs: more social media accounts linked to more anxiety, depression, inattention, FoMO and loneliness, especially when FoMO was high.","whyItMatters":"Adds parent-reported symptoms, reducing reliance on teen self-report alone.","relevance":70,"relevanceReason":"Small but multi-informant","stances":[{"claimId":"c1","stance":"supports","note":"More accounts linked to more symptoms"},{"claimId":"c2","stance":"supports","note":"FoMO moderates the association"},{"claimId":"c3","stance":"unclear","note":"not stated"}],"methodology":"Cross-sectional survey of 226 parent and adolescent participants.","limitations":"Small sample; cross-sectional; account count is a crude measure.","useAs":"evidence"}'::jsonb, '{"score":94,"inputs":{"citationCount":473,"peerReviewed":true,"venueType":"journal","year":2017}}'::jsonb),
  ('00000000-0000-4000-8000-000000000001', 'openalex-W4412465318', '{"paperId":"openalex-W4412465318","projectId":"00000000-0000-4000-8000-000000000001","overview":"Survey of 1,563 Bahamian Grade 9 students: two-thirds used social media 3+ hours daily; online risks like cyberbullying and sexting linked to risk behaviours and poorer mental health.","whyItMatters":"Shows online risk experiences, not just screen time, matter.","relevance":68,"relevanceReason":"Caribbean context, risk focus","stances":[{"claimId":"c1","stance":"neutral","note":"Associations, focus on risk behaviours"},{"claimId":"c2","stance":"supports","note":"Online risk experiences drive harm"},{"claimId":"c3","stance":"unclear","note":"not stated"}],"methodology":"School survey analysed with generalized linear mixed models.","limitations":"Cross-sectional; one island population.","useAs":"evidence"}'::jsonb, '{"score":71,"inputs":{"citationCount":4,"peerReviewed":true,"venueType":"journal","year":2025}}'::jsonb),
  ('00000000-0000-4000-8000-000000000001', 'openalex-W4307381759', '{"paperId":"openalex-W4307381759","projectId":"00000000-0000-4000-8000-000000000001","overview":"Conference abstract of the UK Understanding Society analysis: hours on social media at 12–13 predicted mental health difficulties at 14–15 via self-esteem.","whyItMatters":"Earlier version of the longitudinal UK finding — cite the full paper instead.","relevance":60,"relevanceReason":"Duplicate of fuller study","stances":[{"claimId":"c1","stance":"supports","note":"Earlier use predicts later difficulties"},{"claimId":"c2","stance":"unclear","note":"not stated"},{"claimId":"c3","stance":"unclear","note":"not stated"}],"methodology":"Multilevel regression and structural equation path analysis.","limitations":"Conference abstract; limited detail.","useAs":"evidence"}'::jsonb, '{"score":67,"inputs":{"citationCount":5,"peerReviewed":true,"venueType":"journal","year":2022}}'::jsonb),
  ('00000000-0000-4000-8000-000000000001', 'openalex-W4401979739', '{"paperId":"openalex-W4401979739","projectId":"00000000-0000-4000-8000-000000000001","overview":"Qualitative study of Indian adolescents'' perceptions of social media, describing benefits like connection alongside harms of excessive use after COVID-19.","whyItMatters":"Non-Western, qualitative voices to broaden your evidence base.","relevance":58,"relevanceReason":"Different context and method","stances":[{"claimId":"c1","stance":"neutral","note":"Reports both benefits and harms"},{"claimId":"c2","stance":"supports","note":"Harm linked to excessive use"},{"claimId":"c3","stance":"unclear","note":"not stated"}],"methodology":"Qualitative study of Indian adolescents.","limitations":"Small, non-representative sample likely; not stated in abstract.","useAs":"background"}'::jsonb, '{"score":80,"inputs":{"citationCount":18,"peerReviewed":true,"venueType":"journal","year":2024}}'::jsonb),
  ('00000000-0000-4000-8000-000000000001', 'openalex-W4403107816', '{"paperId":"openalex-W4403107816","projectId":"00000000-0000-4000-8000-000000000001","overview":"Study of 138 adolescents aged 16–19: more intense social media use predicted worse mental health while physical activity predicted better mental health.","whyItMatters":"Small study linking intensity to harm and activity to protection.","relevance":55,"relevanceReason":"Small sample, simple design","stances":[{"claimId":"c1","stance":"supports","note":"Intensity negatively predicted mental health"},{"claimId":"c2","stance":"unclear","note":"not stated"},{"claimId":"c3","stance":"unclear","note":"not stated"}],"methodology":"Ex post facto regression using GHQ-12, SONTUS and PAQ-A.","limitations":"Small sample of 138; cross-sectional.","useAs":"evidence"}'::jsonb, '{"score":60,"inputs":{"citationCount":0,"peerReviewed":true,"venueType":"journal","year":2024}}'::jsonb),
  ('00000000-0000-4000-8000-000000000001', 'openalex-W4380631524', '{"paperId":"openalex-W4380631524","projectId":"00000000-0000-4000-8000-000000000001","overview":"Survey of 272 Thai teenagers on how social media affects their mental health, aiming to suggest ways to reduce negative effects.","whyItMatters":"Adds a Southeast Asian sample but evidence is weak.","relevance":40,"relevanceReason":"Small, low-credibility survey","stances":[{"claimId":"c1","stance":"supports","note":"Associates use with negative effects"},{"claimId":"c2","stance":"unclear","note":"not stated"},{"claimId":"c3","stance":"unclear","note":"not stated"}],"methodology":"Questionnaire survey of 272 respondents.","limitations":"Small convenience sample; limited methodology detail.","useAs":"background"}'::jsonb, '{"score":68,"inputs":{"citationCount":5,"peerReviewed":true,"venueType":"journal","year":2023}}'::jsonb)
