-- GENERATED by scripts/generate-prod-demo.mjs from src/fixtures/papers.json — do not edit by hand.
-- Production demo project (RD-02). No login is created: the owner has no password or identity.
-- Safe to run more than once; re-running resets the demo's join code, analyses and starter saves
-- (members — i.e. any guest — can edit analyses). Paste into Supabase → SQL Editor → Run.
begin;

-- Owner account (cannot sign in: no password, no identity)
values (
  '00000000-0000-0000-0000-000000000000', '00000000-0000-4000-8000-0000000000d0', 'authenticated', 'authenticated',
  'demo-owner@papercut.invalid', '{"provider":"email","providers":[]}', '{"full_name":"PaperCut demo"}', now(), now()
)
on conflict (id) do nothing;

-- Demo project (owner membership is added by the on_project_created trigger)
  '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-0000000000d0', 'Social media & teen mental health', 'social media use adolescent mental health', '{"topic":"Does social media use harm adolescent mental health?","claims":[{"id":"c1","text":"Heavier social media use causes poorer adolescent mental health."},{"id":"c2","text":"How teens use social media matters more than how much they use it."},{"id":"c3","text":"Teaching healthy-use skills works better than restricting access."}],"themes":["depression and anxiety","problematic use","social comparison","interventions"],"constraints":["Published 2015 or later","Adolescents aged 10–19"],"summary":"A 2,500-word argumentative essay evaluating whether social media harms teenagers'' mental health, weighing causal evidence against usage-pattern explanations and recommending interventions."}'::jsonb, 'DEMO42'
)
on conflict (id) do update set
  title = excluded.title, query = excluded.query, context = excluded.context, join_code = excluded.join_code;

-- Fixture papers (real OpenAlex records); keep any fresher cached copy
on conflict do nothing;

-- Analyses + computed credibility for the demo project
on conflict (project_id, paper_id) do update set
  analysis = excluded.analysis, credibility = excluded.credibility;

-- Starter swipes by the owner so the library and exports aren't empty
on conflict (project_id, paper_id, user_id) do update set decision = excluded.decision;

commit;

-- Check: expect 1 project, 20 papers, 20 analyses, 5 saves.
select
  (select count(*) from public.projects where join_code = 'DEMO42') as projects,
  (select count(*) from public.paper_analyses where project_id = '00000000-0000-4000-8000-000000000001') as analyses,
  (select count(*) from public.swipes where project_id = '00000000-0000-4000-8000-000000000001' and decision = 'save') as saves;
